import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.apache.lucene.document.Document;
import org.apache.lucene.document.Field;
import org.apache.lucene.document.LatLonShape;
import org.apache.lucene.document.ShapeField.QueryRelation;
import org.apache.lucene.geo.Line;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.index.IndexReader;
import org.apache.lucene.index.IndexWriter;
import org.apache.lucene.index.IndexWriterConfig;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.Query;
import org.apache.lucene.search.ScoreDoc;
import org.apache.lucene.store.ByteBuffersDirectory;
import org.apache.lucene.store.Directory;

/** Brute-force search for a false-positive CONTAINS with very flat polygons. */
public class Repro {
  static final double QUANTUM = 180.0 / Math.pow(2, 32); // approx lat quantum

  static int indexPoly(Directory dir, Polygon p) throws Exception {
    try (IndexWriter w = new IndexWriter(dir, new IndexWriterConfig())) {
      Document d = new Document();
      for (Field f : LatLonShape.createIndexableFields("f", p)) {
        d.add(f);
      }
      w.addDocument(d);
    }
    return 0;
  }

  static int search(Directory dir, Query q) throws Exception {
    try (IndexReader r = new org.apache.lucene.index.DirectoryReader(dir) {}.openIfChanged(null)) {
      return -1;
    } catch (Throwable t) {
      // fallthrough to simple approach below
    }
    return -1;
  }

  static int countMatches(Directory dir, Query q) throws Exception {
    IndexWriterConfig cfg = new IndexWriterConfig();
    try (IndexWriter w = new IndexWriter(dir, new IndexWriterConfig())) {
      w.commit();
    }
    try (IndexReader r = org.apache.lucene.index.DirectoryReader.open(dir)) {
      IndexSearcher s = new IndexSearcher(r);
      ScoreDoc[] hits = s.search(q, 10).scoreDocs;
      return hits.length;
    }
  }

  /** checks whether a decoded triangle degenerates to a line via the buggy a==b branch */
  public static void main(String[] args) throws Exception {
    Random rnd = new Random(Long.parseLong(args.length > 0 ? args[0] : "42"));
    int found = 0;
    for (int iter = 0; iter < 40000 && found < 3; iter++) {
      // build a flat polygon: long in lon, thin in lat
      int n = 4 + rnd.nextInt(3);
      double lon0 = rnd.nextDouble() * 40 - 20;
      double lonSpan = 0.5 + rnd.nextDouble() * 5;
      double lat0 = rnd.nextDouble() * 40 - 20;
      // thickness: mix of sub-quantum and a few quanta
      double thickness = QUANTUM * (rnd.nextDouble() < 0.5 ? rnd.nextDouble() * 0.9 : 1 + rnd.nextDouble() * 4);
      double[] lons = new double[n + 1];
      double[] lats = new double[n + 1];
      // top edge west->east, bottom edge east->west
      int m = (n) / 2;
      List<double[]> pts = new ArrayList<>();
      for (int i = 0; i <= m; i++) {
        double lon = lon0 + lonSpan * i / m;
        // jitter lat a bit; sometimes collapses
        double lat = lat0 + thickness * (rnd.nextDouble() < 0.3 ? 0 : rnd.nextDouble());
        pts.add(new double[] {lat, lon});
      }
      for (int i = m; i >= 0; i--) {
        double lon = lon0 + lonSpan * i / m;
        double lat = lat0 + thickness * (rnd.nextDouble() < 0.3 ? 0 : rnd.nextDouble());
        pts.add(new double[] {lat, lon});
      }
      // close
      pts.add(pts.get(0));
      double[] plons = new double[pts.size()];
      double[] plats = new double[pts.size()];
      for (int i = 0; i < pts.size(); i++) {
        plats[i] = pts.get(i)[0];
        plons[i] = pts.get(i)[1];
      }
      Polygon indexed;
      try {
        indexed = new Polygon(plats, plons);
      } catch (Exception e) {
        continue;
      }
      Directory dir = new ByteBuffersDirectory();
      try {
        indexPoly(dir, indexed);
      } catch (Exception e) {
        dir.close();
        continue;
      }
      // query: a polygon that intersects but is definitely NOT contained (sticks out in lat)
      double qLon = lon0 + lonSpan / 2;
      double qLat = lat0 + thickness;
      Polygon query =
          new Polygon(
              new double[] {qLat, qLat + 2, qLat + 2, qLat, qLat},
              new double[] {qLon - 1, qLon - 1, qLon + 1, qLon + 1, qLon - 1});
      Query q = LatLonShape.newPolygonQuery("f", QueryRelation.CONTAINS, query);
      int matches = countMatches(dir, q);
      if (matches > 0) {
        // also try line query crossing
        Line ql =
            new Line(
                new double[] {lat0 - 1, qLat, lat0 + 3},
                new double[] {qLon, qLon, qLon});
        Query q2 = LatLonShape.newLineQuery("f", QueryRelation.CONTAINS, ql);
        int m2 = countMatches(dir, q2);
        System.out.println("iter=" + iter + " matches=" + matches + " lineMatches=" + m2);
        System.out.println("indexed polygon lats=" + java.util.Arrays.toString(plats));
        System.out.println("indexed polygon lons=" + java.util.Arrays.toString(plons));
        found++;
      }
      dir.close();
    }
    System.out.println("found=" + found);
  }
}

