import org.apache.lucene.search.ScoreDoc;
import org.apache.lucene.store.ByteBuffersDirectory;
import org.apache.lucene.store.Directory;

/**
 * Searches for flat polygons where a tessellation triangle degenerates to a line whose
 * "from polygon" flag is taken from the collapsed edge instead of the retained segment.
 */
public class Finder {
  static byte[] scratch = new byte[7 * ShapeField.BYTES];

  // simulate encode->decode for a tess triangle; returns decoded triangle
  static DecodedTriangle sim(Tessellator.Triangle t) {
    int[] xs = new int[] {t.getEncodedX(0), t.getEncodedX(1), t.getEncodedX(2)};
    int[] ys = new int[] {t.getEncodedY(0), t.getEncodedY(1), t.getEncodedY(2)};
    boolean[] f = new boolean[] {t.isEdgefromPolygon(0), t.isEdgefromPolygon(1), t.isEdgefromPolygon(2)};
    ShapeField.encodeTriangle(scratch, ys[0], xs[0], f[0], ys[1], xs[1], f[1], ys[2], xs[2], f[2]);
    DecodedTriangle dt = new DecodedTriangle();
    ShapeField.decodeTriangle(scratch, dt);
    return dt;
  }

  // ground truth: flag of the original edge matching direction (aX,aY)->(bX,bY), or null
  static Boolean gtFlag(Tessellator.Triangle t, int aX, int aY, int bX, int bY) {
    int[] xs = new int[] {t.getEncodedX(0), t.getEncodedX(1), t.getEncodedX(2)};
    int[] ys = new int[] {t.getEncodedY(0), t.getEncodedY(1), t.getEncodedY(2)};
    boolean[] f = new boolean[] {t.isEdgefromPolygon(0), t.isEdgefromPolygon(1), t.isEdgefromPolygon(2)};
    for (int i = 0; i < 3; i++) {
      int j = (i + 1) % 3;
      if (xs[i] == aX && ys[i] == aY && xs[j] == bX && ys[j] == bY) return f[i];
      if (xs[i] == bX && ys[i] == bY && xs[j] == aX && ys[j] == aY) return f[i];
    }
    return null;
  }

  static int countMatches(Directory dir, Query q) throws Exception {
    try (IndexReader r = DirectoryReader.open(dir)) {
      IndexSearcher s = new IndexSearcher(r);
      ScoreDoc[] hits = s.search(q, 10).scoreDocs;
      return hits.length;
    }
  }

  public static void main(String[] args) throws Exception {
    Random rnd = new Random(Long.parseLong(args.length > 0 ? args[0] : "42"));
    int found = 0;
    long tries = 0;
    while (found < 3 && tries < 200000) {
      tries++;
      int n = 4 + rnd.nextInt(4);
      double lon0 = rnd.nextDouble() * 40 - 20;
      double lonSpan = 0.5 + rnd.nextDouble() * 5;
      double lat0 = rnd.nextDouble() * 40 - 20;
      double quantum = 180.0 / Math.pow(2, 32);
      double thickness = quantum * (rnd.nextDouble() < 0.7 ? rnd.nextDouble() * 1.5 : 1 + rnd.nextDouble() * 5);
      int m = n / 2;
      java.util.List<double[]> pts = new java.util.ArrayList<>();
      for (int i = 0; i <= m; i++) {
        double lon = lon0 + lonSpan * i / m;
        double lat = lat0 + thickness * (rnd.nextDouble() < 0.35 ? 0 : rnd.nextDouble());
        pts.add(new double[] {lat, lon});
      }
      for (int i = m; i >= 0; i--) {
        double lon = lon0 + lonSpan * i / m;
        double lat = lat0 + thickness * (rnd.nextDouble() < 0.35 ? 0 : rnd.nextDouble());
        pts.add(new double[] {lat, lon});
      }
      pts.add(pts.get(0));
      double[] plons = new double[pts.size()];
      double[] plats = new double[pts.size()];
      for (int i = 0; i < pts.size(); i++) {
        plats[i] = pts.get(i)[0];
        plons[i] = pts.get(i)[1];
      }
      Polygon indexed;
      try {
        indexed = new Polygon(plats, plons);
      } catch (Exception e) {
        continue;
      }
      List<Tessellator.Triangle> tess;
      try {
        tess = Tessellator.tessellate(indexed, true);
      } catch (Exception e) {
        continue;
      }
      // find degenerate LINE triangles with flag inconsistency
      for (Tessellator.Triangle t : tess) {
        DecodedTriangle dt = sim(t);
        if (dt.type == DecodedTriangle.TYPE.LINE) {
          Boolean gt = gtFlag(t, dt.aX, dt.aY, dt.bX, dt.bY);
          if (gt == null) continue;
          if (gt != dt.ab) {
            // bug condition: reported flag differs from ground truth of retained segment
            System.out.println("FLAG-INCONSISTENCY: reported=" + dt.ab + " gt=" + gt);
            System.out.println("lats=" + Arrays.toString(plats));
            System.out.println("lons=" + Arrays.toString(plons));
            found++;
            break;
          }
        }
      }
    }
    System.out.println("tries=" + tries + " found=" + found);
  }
}

