/** Integration repro: CONTAINS false positive with a very flat polygon. */
public class Repro2 {
  static byte[] scratch = new byte[7 * 4];

  // the flat polygon found by Finder (seed 42, first hit)
  static final double[] LATS = {
    17.68294174442644, 17.68294176765135, 17.682941730405012,
    17.68294177794017, 17.68294173031889, 17.682941721128515,
    17.682941721128515, 17.6829417308138, 17.68294174442644
  };
  static final double[] LONS = {
    -17.81338949011357, -17.566823981551256, -17.320258472988943,
    -17.07369296442663, -17.07369296442663, -17.320258472988943,
    -17.566823981551256, -17.81338949011357, -17.81338949011357
  };

  static DecodedTriangle sim(Tessellator.Triangle t) {
    int[] xs = new int[] {t.getEncodedX(0), t.getEncodedX(1), t.getEncodedX(2)};
    int[] ys = new int[] {t.getEncodedY(0), t.getEncodedY(1), t.getEncodedY(2)};
    boolean[] f = new boolean[] {t.isEdgefromPolygon(0), t.isEdgefromPolygon(1), t.isEdgefromPolygon(2)};
    ShapeField.encodeTriangle(scratch, ys[0], xs[0], f[0], ys[1], xs[1], f[1], ys[2], xs[2], f[2]);
    DecodedTriangle dt = new DecodedTriangle();
    ShapeField.decodeTriangle(scratch, dt);
    return dt;
  }

  static Boolean gtFlag(Tessellator.Triangle t, int aX, int aY, int bX, int bY) {
    int[] xs = new int[] {t.getEncodedX(0), t.getEncodedX(1), t.getEncodedX(2)};
    int[] ys = new int[] {t.getEncodedY(0), t.getEncodedY(1), t.getEncodedY(2)};
    boolean[] f = new boolean[] {t.isEdgefromPolygon(0), t.isEdgefromPolygon(1), t.isEdgefromPolygon(2)};
    for (int i = 0; i < 3; i++) {
      int j = (i + 1) % 3;
      if (xs[i] == aX && ys[i] == aY && xs[j] == bX && ys[j] == bY) return f[i];
      if (xs[i] == bX && ys[i] == bY && xs[j] == aX && ys[j] == aY) return f[i];
    }
    return null;
  }

  static int countMatches(Directory dir, Query q) throws Exception {
    try (IndexReader r = DirectoryReader.open(dir)) {
      IndexSearcher s = new IndexSearcher(r);
      return s.search(q, 10).scoreDocs.length;
    }
  }

  public static void main(String[] args) throws Exception {
    Polygon indexed = new Polygon(LATS, LONS);
    Directory dir = new ByteBuffersDirectory();
    try (IndexWriter w = new IndexWriter(dir, new IndexWriterConfig())) {
      Document d = new Document();
      for (Field f : LatLonShape.createIndexableFields("f", indexed)) {
        d.add(f);
      }
      w.addDocument(d);
      w.commit();
    }

    // locate a mis-flagged degenerate line segment
    List<Tessellator.Triangle> tess = Tessellator.tessellate(indexed, true);
    double[] seg = null; // {aLon, aLat, bLon, bLat}
    boolean gt = false;
    for (Tessellator.Triangle t : tess) {
      DecodedTriangle dt = sim(t);
      if (dt.type == DecodedTriangle.TYPE.LINE) {
        Boolean g = gtFlag(t, dt.aX, dt.aY, dt.bX, dt.bY);
        if (g != null && g != dt.ab) {
