                GeoEncodingUtils.decodeLatitude(dt.aY),
                GeoEncodingUtils.decodeLongitude(dt.bX),
                GeoEncodingUtils.decodeLatitude(dt.bY)
              };
          gt = g;
          break;
        }
      }
    }
    if (seg == null) {
      System.out.println("no mis-flagged segment found");
      return;
    }
    System.out.println("mis-flagged segment: " + Arrays.toString(seg) + " gtFlag=" + gt);

    // midpoint of segment
    double mLon = (seg[0] + seg[2]) / 2;
    double mLat = (seg[1] + seg[3]) / 2;
    // segment direction and normal
    double dLon = seg[2] - seg[0];
    double dLat = seg[3] - seg[1];
    double len = Math.sqrt(dLon * dLon + dLat * dLat);
    double nLon = -dLat / len;
    double nLat = dLon / len;
    double eps = 1e-6;
    // probe which side is inside the polygon using CONTAINS point queries
    double[] probeIn = {mLat + nLat * eps, mLon + nLon * eps};
    double[] probeOut = {mLat - nLat * eps, mLon - nLon * eps};
    Query pin = LatLonShape.newPointQuery("f", QueryRelation.CONTAINS, probeIn);
    Query pout = LatLonShape.newPointQuery("f", QueryRelation.CONTAINS, probeOut);
    boolean sideIn = countMatches(dir, pin) > 0;
    boolean sideOut = countMatches(dir, pout) > 0;
    System.out.println("probe +side inside=" + sideIn + "  -side inside=" + sideOut);
    if (sideIn == sideOut) {
      System.out.println("probes ambiguous, aborting");
      return;
    }
    double inLon, inLat, outLon, outLat;
    if (sideIn) {
      inLat = nLat; inLon = nLon; outLat = -nLat; outLon = -nLon;
    } else {
      inLat = -nLat; inLon = -nLon; outLat = nLat; outLon = nLon;
    }
    // query line: starts outside across the edge, goes into the polygon along the edge
    // direction, ending inside the polygon
    double along = len * 0.4;
    double oLat = mLat + outLat * eps * 5;
    double oLon = mLon + outLon * eps * 5;
    double iLat = mLat + inLat * eps * 2 + dLat / len * along;
    double iLon = mLon + inLon * eps * 2 + dLon / len * along;
    Line ql = new Line(new double[] {oLat, iLat}, new double[] {oLon, iLon});
    // sanity: whole line is NOT contained because one endpoint is outside
    Query containsQuery = LatLonShape.newLineQuery("f", QueryRelation.CONTAINS, ql);
