    double f1Lat = mLat + inLat * eps * 5;
    double f1Lon = mLon + inLon * eps * 5;
    double f2Lat = f1Lat + dLat / len * (len * 0.2);
    double f2Lon = f1Lon + dLon / len * (len * 0.2);
    Line inner = new Line(new double[] {f1Lat, f2Lat}, new double[] {f1Lon, f2Lon});
    int innerMatches = countMatches(dir, LatLonShape.newLineQuery("f", QueryRelation.CONTAINS, inner));
    System.out.println("CONTAINS(inside line) matches=" + innerMatches);
    dir.close();
  }
}

