    Random rnd = new Random(Long.parseLong(args.length > 0 ? args[0] : "42"));
    long tries = 0;
    int tested = 0;
    while (tested < 40 && tries < 300000) {
      tries++;
      int n = 4 + rnd.nextInt(4);
      double lon0 = rnd.nextDouble() * 40 - 20;
      double lonSpan = 0.5 + rnd.nextDouble() * 5;
      double lat0 = rnd.nextDouble() * 40 - 20;
      double thickness =
          QUANTUM * (rnd.nextDouble() < 0.7 ? rnd.nextDouble() * 1.5 : 1 + rnd.nextDouble() * 5);
      int m = n / 2;
      List<double[]> pts = new ArrayList<>();
      for (int i = 0; i <= m; i++) {
        double lon = lon0 + lonSpan * i / m;
        double lat = lat0 + thickness * (rnd.nextDouble() < 0.35 ? 0 : rnd.nextDouble());
        pts.add(new double[] {lat, lon});
      }
      for (int i = m; i >= 0; i--) {
        double lon = lon0 + lonSpan * i / m;
        double lat = lat0 + thickness * (rnd.nextDouble() < 0.35 ? 0 : rnd.nextDouble());
        pts.add(new double[] {lat, lon});
      }
      pts.add(pts.get(0));
      double[] plons = new double[pts.size()];
      double[] plats = new double[pts.size()];
      for (int i = 0; i < pts.size(); i++) {
        plats[i] = pts.get(i)[0];
        plons[i] = pts.get(i)[1];
      }
      Polygon indexed;
      try {
        indexed = new Polygon(plats, plons);
      } catch (Exception e) {
        continue;
      }
      List<Tessellator.Triangle> tess;
      try {
        tess = Tessellator.tessellate(indexed, true);
      } catch (Exception e) {
        continue;
      }
      boolean hasMis = false;
      double[] seg = null;
      for (Tessellator.Triangle t : tess) {
        DecodedTriangle dt = sim(t);
        if (dt.type == DecodedTriangle.TYPE.LINE) {
          Boolean g = gtFlag(t, dt.aX, dt.aY, dt.bX, dt.bY);
          if (g != null && g != dt.ab) {
            seg =
                new double[] {
                  GeoEncodingUtils.decodeLongitude(dt.aX),
                  GeoEncodingUtils.decodeLatitude(dt.aY),
                  GeoEncodingUtils.decodeLongitude(dt.bX),
                  GeoEncodingUtils.decodeLatitude(dt.bY)
                };
            hasMis = true;
            break;
          }
        }
      }
      if (!hasMis) continue;
      Directory dir = new ByteBuffersDirectory();
      try {
        indexDoc(dir, indexed);
      } catch (Exception e) {
        dir.close();
        continue;
      }
      tested++;
      // midpoint of the mis-flagged segment
      double mLon = (seg[0] + seg[2]) / 2;
      double mLat = (seg[1] + seg[3]) / 2;
      double dLon = seg[2] - seg[0];
      double dLat = seg[3] - seg[1];
      double len = Math.sqrt(dLon * dLon + dLat * dLat);
      double uLon = dLon / len, uLat = dLat / len; // along edge
      double nLon = -uLat, nLat = uLon; // normal
      double[] widths = {len * 0.05, len * 0.15};
      double[] depths = {0.5 * QUANTUM, QUANTUM, 2 * QUANTUM};
      for (double w : widths) {
        for (double h : depths) {
          // rectangle straddling the edge, first vertex inside (below edge, +normal)
          double[][] rect = {
            {mLat + nLat * h, mLon + nLon * h},
            {mLat - uLat * w + nLat * h, mLon - uLon * w + nLon * h},
            {mLat - uLat * w - nLat * h, mLon - uLon * w - nLon * h},
            {mLat + uLat * w - nLat * h, mLon + uLon * w - nLon * h},
            {mLat + nLat * h, mLon + nLon * h}
          };
          double[] rlats = new double[5];
          double[] rlons = new double[5];
          for (int i = 0; i < 5; i++) {
