            rlons[i] = rect[i][1];
          }
          Polygon qp;
          try {
            qp = new Polygon(rlats, rlons);
          } catch (Exception e) {
            continue;
          }
          Query q = LatLonShape.newPolygonQuery("f", QueryRelation.CONTAINS, qp);
          int m0 = countMatches(dir, q);
          int ix = countMatches(dir, LatLonShape.newPolygonQuery("f", QueryRelation.INTERSECTS, qp));
          if (m0 > 0) {
