import java.util.Arrays;
import java.util.List;
import java.util.Random;
import org.apache.lucene.document.Document;
import org.apache.lucene.document.Field;
import org.apache.lucene.document.LatLonShape;
import org.apache.lucene.document.ShapeField.QueryRelation;
import org.apache.lucene.geo.Line;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.index.DirectoryReader;
import org.apache.lucene.index.IndexReader;
import org.apache.lucene.index.IndexWriter;
import org.apache.lucene.index.IndexWriterConfig;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.Query;
import org.apache.lucene.store.ByteBuffersDirectory;
import org.apache.lucene.store.Directory;

/**
 * Regression sanity: on non-degenerate shapes, results must be identical across many
 * random polygons/queries; and positive CONTAINS cases must still match.
 */
public class Sanity {
  static int countMatches(Directory dir, Query q) throws Exception {
    try (IndexReader r = DirectoryReader.open(dir)) {
      return new IndexSearcher(r).search(q, 10).scoreDocs.length;
    }
  }

  static void indexDoc(Directory dir, Polygon p) throws Exception {
    try (IndexWriter w = new IndexWriter(dir, new IndexWriterConfig())) {
      Document d = new Document();
      for (Field f : LatLonShape.createIndexableFields("f", p)) {
        d.add(f);
      }
      w.addDocument(d);
      w.commit();
    }
  }

  public static void main(String[] args) throws Exception {
    Random rnd = new Random(Long.parseLong(args.length > 0 ? args[0] : "1"));
    int mismatches = 0;
    int checked = 0;
    int containsPositives = 0;
    for (int iter = 0; iter < 200; iter++) {
      // normal random polygon (not flat)
      int n = 3 + rnd.nextInt(5);
      double lat0 = rnd.nextDouble() * 40 - 20;
      double lon0 = rnd.nextDouble() * 40 - 20;
      double[] lats = new double[n + 1];
      double[] lons = new double[n + 1];
      double radius = 0.1 + rnd.nextDouble() * 2;
      for (int i = 0; i < n; i++) {
        double ang = 2 * Math.PI * i / n + rnd.nextDouble() * 0.3;
        lats[i] = lat0 + radius * Math.sin(ang) * (0.5 + rnd.nextDouble());
        lons[i] = lon0 + radius * Math.cos(ang) * (0.5 + rnd.nextDouble());
      }
      lats[n] = lats[0];
      lons[n] = lons[0];
      Polygon p;
      try {
        p = new Polygon(lats, lons);
      } catch (Exception e) {
        continue;
      }
      Directory dir = new ByteBuffersDirectory();
      try {
        indexDoc(dir, p);
      } catch (Exception e) {
        dir.close();
        continue;
      }
      // queries: boxes/lines/polygons around the centroid
      for (int qi = 0; qi < 6; qi++) {
        double s = radius * (0.2 + rnd.nextDouble() * 1.5);
        double clat = lat0 + (rnd.nextDouble() - 0.5) * radius;
        double clon = lon0 + (rnd.nextDouble() - 0.5) * radius;
        Polygon qp;
        Line ql = null;
        if (qi < 3) {
          qp =
              new Polygon(
                  new double[] {clat - s, clat - s, clat + s, clat + s, clat - s},
                  new double[] {clon - s, clon + s, clon + s, clon - s, clon - s});
        } else {
          qp =
              new Polygon(
                  new double[] {clat, clat + s, clat, clat - s, clat},
                  new double[] {clon - s, clon, clon + s, clon, clon - s});
          ql = new Line(new double[] {clat, clat + s}, new double[] {clon, clon});
        }
        try {
          int cp = countMatches(dir, LatLonShape.newPolygonQuery("f", QueryRelation.CONTAINS, qp));
          int ip = countMatches(dir, LatLonShape.newPolygonQuery("f", QueryRelation.INTERSECTS, qp));
          int wp = countMatches(dir, LatLonShape.newPolygonQuery("f", QueryRelation.WITHIN, qp));
          checked++;
          if (cp > 0 && ip == 0) {
            System.out.println("INCONSISTENT contains>0 intersects=0");
            mismatches++;
          }
          if (cp > 0 && wp == 0) {
            System.out.println("INCONSISTENT contains>0 within=0");
            mismatches++;
          }
          if (cp > 0) containsPositives++;
        } catch (Exception e) {
          System.out.println("EXCEPTION: " + e);
          mismatches++;
        }
      }
      dir.close();
    }
    System.out.println(
        "checked=" + checked + " containsPositives=" + containsPositives + " mismatches=" + mismatches);
  }
}

import java.util.Arrays;
