/** Targeted test on the exact failing polygon from Repro3 seed 42. */
public class Focused {
  static final double[] LATS = {
    -9.011929368326186, -9.011929448858803, -9.011929450951666,
    -9.011929300694186, -9.01192944329501, -9.011929280891712,
    -9.011929368326186
  };
  static final double[] LONS = {
    -18.759624519136132, -18.161884821838882, -17.564145124541632,
    -17.564145124541632, -18.161884821838882, -18.759624519136132,
    -18.759624519136132
  };

  public static void main(String[] args) throws Exception {
    Polygon indexed = new Polygon(LATS, LONS);
    Directory dir = new ByteBuffersDirectory();
    try (IndexWriter w = new IndexWriter(dir, new IndexWriterConfig())) {
      Document d = new Document();
      for (Field f : LatLonShape.createIndexableFields("f", indexed)) {
        d.add(f);
      }
      w.addDocument(d);
      w.commit();
    }
    double w = 0.029886987525970923;
    double h = 2.0954757928848267E-8;
    // segment from the log
    double mLon = (-18.759624576196074 + -18.16188482567668) / 2;
    double mLat = (-9.011929300613701 + -9.011929468251765) / 2;
    double dLon = -18.16188482567668 - -18.759624576196074;
    double dLat = -9.011929468251765 - -9.011929300613701;
    double len = Math.sqrt(dLon * dLon + dLat * dLat);
    double uLon = dLon / len, uLat = dLat / len;
    double nLon = -uLat, nLat = uLon;
    double[] rlats = {
      mLat + nLat * h,
      mLat - uLat * w + nLat * h,
      mLat - uLat * w - nLat * h,
      mLat + uLat * w - nLat * h,
      mLat + nLat * h
    };
    double[] rlons = {
      mLon + nLon * h,
      mLon - uLon * w + nLon * h,
      mLon - uLon * w - nLon * h,
      mLon + uLon * w - nLon * h,
      mLon + nLon * h
    };
    Polygon qp = new Polygon(rlats, rlons);
    try (IndexReader r = DirectoryReader.open(dir)) {
      IndexSearcher s = new IndexSearcher(r);
      int c =
          s.search(LatLonShape.newPolygonQuery("f", QueryRelation.CONTAINS, qp), 10)
              .scoreDocs
              .length;
      int i =
          s.search(LatLonShape.newPolygonQuery("f", QueryRelation.INTERSECTS, qp), 10)
              .scoreDocs
              .length;
      System.out.println("CONTAINS matches=" + c + " (expected 0; query pokes outside)");
      System.out.println("INTERSECTS matches=" + i + " (expected 1)");
    }
    dir.close();
  }
}

